def solve():
    face = Q(46000000)
    rate = Q("2.35")
    base = Q(440000)
    divest = Q(2)
    if divest >= 5:
        applicable = base * (1 - divest / 100)
    else:
        applicable = base
    target = applicable * (1 - Q(10) / 100)
    emissions = Q("74.25") / 100 * base
    if emissions > target * Q("1.05"):
        step = Q("0.20")
    elif emissions > target:
        step = Q("0.10")
    else:
        step = Q(0)
    new_rate = rate + step
    # coupons 2026..2032; verification 30 June 2028 -> coupons 2028..2032 stepped
    years = list(range(2026, 2033))
    total = Q(0)
    count = 0
    for y in years:
        if y >= 2028:
            r = new_rate
            count += 1
        else:
            r = rate
        total += face * r / 100
    return {
        "final": total,
        "applicable_baseline": applicable,
        "emissions_threshold": target,
        "stepped_coupon_rate": new_rate,
        "stepped_coupon_count": count,
    }

def solve():
    face = Q(10000000)
    rate = Q("3.1")
    baseline = Q(480000)
    divest = Q(4)
    if divest >= 5:
        applicable = baseline * (1 - divest / 100)
    else:
        applicable = baseline
    target = applicable * (1 - Q(10) / 100)
    emissions = baseline * Q("89.75") / 100
    excess = (emissions - target) / target
    if excess > Q(5) / 100:
        stepup = Q("0.20")
    elif excess > 0:
        stepup = Q("0.10")
    else:
        stepup = Q(0)
    stepped_rate = rate + stepup
    # coupons 2026..2031; verification 30 June 2028 -> coupons 2028..2031 are on/after (31 Dec)
    years = list(range(2026, 2032))
    total = Q(0)
    count = 0
    for y in years:
        if y >= 2028:
            total += face * stepped_rate / 100
            count += 1
        else:
            total += face * rate / 100
    return {
        "final": total,
        "applicable_baseline": applicable,
        "emissions_threshold": target,
        "stepped_coupon_rate": stepped_rate,
        "stepped_coupon_count": Q(count),
    }
